func TestIntRunRejectsFile(t *testing.T) {
	tmp := t.TempDir()
	t.Chdir(tmp)
	file := filepath.Join(tmp, "afile")
	if err := os.WriteFile(file, []byte("x"), 0o644); err != nil {
		t.Fatal(err)
	}

