	err := rootCmd.Execute()
	if err == nil {
		t.Fatal("expected usage error for non-directory")
	}
	var ue *usageError
	if !errors.As(err, &ue) {
		t.Errorf("expected usageError (exit 2), got %T: %v", err, err)
