18	
19	// apiServer holds the request-independent state for the JSON API.
20	type apiServer struct {
21		root    string
22		version string
23	}
24	
25	// fileDoc is a text document surfaced in an integration's detail view.
26	type fileDoc struct {
27		Name    string `json:"name"`
28		Content string `json:"content"`
29	}
30	
31	// integrationSummary is a scaffold entry plus the coordinates the sidebar
32	// tree groups by: Name is the directory that carries the .intropy record,
33	// System is that directory's parent and Domain the system's parent. System
34	// is empty when the integration sits directly under the workspace root, and
35	// Domain is empty when the system does.
36	type integrationSummary struct {
37		template.ScaffoldEntry
38		Name   string `json:"name"`
39		System string `json:"system,omitempty"`
40		Domain string `json:"domain,omitempty"`
41	}
42	
43	// integrationDetail is a single integration plus best-effort, on-disk
44	// enrichment. Every enrichment field is optional and absent when the
45	// corresponding file or directory does not exist.
46	type integrationDetail struct {
47		integrationSummary
48		Agents        *fileDoc        `json:"agents,omitempty"`
49		Readme        *fileDoc        `json:"readme,omitempty"`
50		Components    []DaprComponent `json:"components,omitempty"`
51		PipelineSteps []string        `json:"pipelineSteps,omitempty"`
52	}
53	
54	// newHandler wires the API routes and the SPA static handler onto a mux.
55	func newHandler(root, version string) (http.Handler, error) {
56		api := &apiServer{root: root, version: version}
57		static, err := staticHandler()
58		if err != nil {
59			return nil, err
60		}
61	
62		mux := http.NewServeMux()
63		mux.HandleFunc("GET /api/health", api.health)
64		mux.HandleFunc("GET /api/integrations", api.listIntegrations)
65		mux.HandleFunc("GET /api/integrations/{path...}", api.getIntegration)
66		mux.HandleFunc("GET /api/flow", api.flow)
67		mux.HandleFunc("GET /api/topology", api.topologies)
68		mux.Handle("/", static)
69		return mux, nil
70	}
71	
72	func (s *apiServer) health(w http.ResponseWriter, _ *http.Request) {
73		writeJSON(w, http.StatusOK, map[string]string{
74			"status":  "ok",
75			"version": s.version,
76		})
77	}
78	
79	// listIntegrations mirrors `int list -o json` — the same scaffold entries in
80	// the same order — with the derived name/system fields added on top and each
81	// Path normalized to a root-relative identifier. The response is always an
82	// array (never null) even when empty.
83	func (s *apiServer) listIntegrations(w http.ResponseWriter, _ *http.Request) {
84		entries, _ := template.ListScaffolds(s.root)
85		summaries := make([]integrationSummary, 0, len(entries))
86		for _, e := range entries {
87			summaries = append(summaries, s.summarize(e))
88		}
89		writeJSON(w, http.StatusOK, summaries)
90	}
91	
92	// summarize derives an entry's tree coordinates from its path. The workspace
93	// root itself never counts as a system or domain, so an integration
94	// scaffolded at the root has neither and one directly under the root has a
95	// system but no domain. The served Path is made root-relative so it is a
96	// stable, URL-safe identifier regardless of whether run was given a relative
97	// or absolute root (an absolute path would otherwise break detail lookups).
98	func (s *apiServer) summarize(e template.ScaffoldEntry) integrationSummary {
99		sum := integrationSummary{ScaffoldEntry: e, Name: filepath.Base(e.Path)}
100		sum.Path = s.relPath(e.Path)
101		path, root := filepath.Clean(e.Path), filepath.Clean(s.root)
102		parent := filepath.Dir(path)
103		if path == root || parent == root {
104			return sum
105		}
106		sum.System = filepath.Base(parent)
107		if grand := filepath.Dir(parent); grand != root {
108			sum.Domain = filepath.Base(grand)
109		}
110		return sum
111	}
112	
113	// relPath turns an entry's on-disk path into the root-relative, slash-separated
114	// identifier used in API responses and URLs. It falls back to the cleaned path
115	// so a value is always produced even if Rel fails (e.g. differing volumes).
116	func (s *apiServer) relPath(p string) string {
117		if rel, err := filepath.Rel(s.root, p); err == nil {
118			return filepath.ToSlash(rel)
119		}
120		return filepath.ToSlash(filepath.Clean(p))
121	}
122	
123	// flow returns every integration enriched with the pipeline steps and Dapr
124	// components the flow canvas draws, so the whole graph loads in one request.
125	// It reuses integrationDetail but leaves the document fields (agents/readme)
126	// nil — the canvas nodes do not render them.
127	func (s *apiServer) flow(w http.ResponseWriter, _ *http.Request) {
128		entries, _ := template.ListScaffolds(s.root)
129		nodes := make([]integrationDetail, 0, len(entries))
130		for _, e := range entries {
131			dir := e.Path
132			nodes = append(nodes, integrationDetail{
133				integrationSummary: s.summarize(e),
134				Components:         readComponents(filepath.Join(dir, "local", "dapr-components")),
135				PipelineSteps:      listNames(filepath.Join(dir, "src", "Process", "Steps")),
136			})
137		}
138		writeJSON(w, http.StatusOK, nodes)
139	}
140	
141	// topologies returns every declared system topology found under the root,
142	// each Path normalized to the same root-relative identifier integration
143	// paths use, so the flow canvas can match a topology to the integrations
144	// living beneath it. Systems without a record are simply absent — the
145	// canvas falls back to its heuristics for those. The response is always an
146	// array (never null) even when empty.
147	func (s *apiServer) topologies(w http.ResponseWriter, _ *http.Request) {
148		entries, _ := topology.List(s.root)
149		out := make([]topology.Entry, 0, len(entries))
150		for _, e := range entries {
151			e.Path = s.relPath(e.Path)
152			out = append(out, e)
153		}
154		writeJSON(w, http.StatusOK, out)
155	}
156	
157	func (s *apiServer) getIntegration(w http.ResponseWriter, r *http.Request) {
158		want := strings.Trim(r.PathValue("path"), "/")
159		// An integration at the workspace root has the identifier "." (see
160		// relPath), but a browser strips the "." segment from /api/integrations/.
161		// so it arrives empty — treat the two as the same request.
162		if want == "" {
163			want = "."
164		}
165		entries, _ := template.ListScaffolds(s.root)
166		for _, e := range entries {
167			if s.relPath(e.Path) == want {
168				writeJSON(w, http.StatusOK, s.enrich(e))
169				return
170			}
171		}
172		writeError(w, http.StatusNotFound, "integration not found: "+want)
173	}
174	
175	// enrich reads optional on-disk context for an integration. The entry's Path
176	// is already usable from the process working directory (see ListScaffolds), so
177	// it doubles as the project directory.
178	func (s *apiServer) enrich(e template.ScaffoldEntry) integrationDetail {
179		dir := e.Path
180		return integrationDetail{
181			integrationSummary: s.summarize(e),
182			Agents:             readDoc(dir, "AGENTS.md"),
183			Readme:             readDoc(dir, "README.md"),
184			Components:         readComponents(filepath.Join(dir, "local", "dapr-components")),
185			PipelineSteps:      listNames(filepath.Join(dir, "src", "Process", "Steps")),
186		}
187	}
188	
189	// readDoc returns the named text file's (possibly truncated) contents, or nil
190	// if it is absent or unreadable.
191	func readDoc(dir, name string) *fileDoc {
192		data, err := os.ReadFile(filepath.Join(dir, name))
193		if err != nil {
194			return nil
195		}
196		if len(data) > maxDocBytes {
197			data = data[:maxDocBytes]
198		}
199		return &fileDoc{Name: name, Content: string(data)}
200	}
201	
202	// listNames returns the sorted base names of the files directly under dir, or
203	// nil if dir is absent or unreadable.
204	func listNames(dir string) []string {
205		ents, err := os.ReadDir(dir)
206		if err != nil {
207			return nil
208		}
209		var names []string
210		for _, ent := range ents {
211			if !ent.IsDir() {
212				names = append(names, ent.Name())
213			}
214		}
215		sort.Strings(names)
216		return names
217	}
218	
219	func writeJSON(w http.ResponseWriter, status int, v any) {
220		w.Header().Set("Content-Type", "application/json; charset=utf-8")
221		w.WriteHeader(status)
222		enc := json.NewEncoder(w)
223		enc.SetIndent("", "  ")
224		_ = enc.Encode(v)
225	}
226	
227	func writeError(w http.ResponseWriter, status int, msg string) {
228		writeJSON(w, status, map[string]string{"error": msg})
229	}
