// blocks returns the workspace's scaffold entries minus the support projects:
// a system host and its shared contracts library are infrastructure the
// system view already represents, not integrations to catalog.
func (s *apiServer) blocks() []template.ScaffoldEntry {
	entries, _ := template.ListScaffolds(s.root)
	kept := entries[:0]
	for _, e := range entries {
		if e.Role == template.RoleSystemHost || e.Role == template.RoleSharedLibrary {
			continue
		}
		kept = append(kept, e)
	}
	return kept
}

